import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse('{"title":"Installieren","description":"","frontmatter":{},"headers":[],"relativePath":"start/installieren.md","filePath":"start/installieren.md"}'),i={name:"start/installieren.md"};function s(d,e,o,l,h,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h1><p>Shardwing gibt es als <strong>Desktop-App</strong> für Windows und macOS. Sie arbeitet direkt mit deinen Dateien: Mission öffnen, bearbeiten, an derselben Stelle speichern.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System</th><th>Datei</th></tr></thead><tbody><tr><td>Windows 10/11 (x64)</td><td><code>Shardwing_&lt;version&gt;_x64-setup.exe</code></td></tr><tr><td>macOS 12 oder neuer (Apple Silicon)</td><td><code>Shardwing_&lt;version&gt;_aarch64.dmg</code></td></tr></tbody></table><p>Beides liegt beim <strong><a href="https://github.com/Leichtester/shardwing-releases/releases/latest" target="_blank" rel="noreferrer">neuesten Release</a></strong>.</p><div class="warning custom-block"><p class="custom-block-title">Noch nicht code-signiert</p><p>Beim ersten Start warnt das System deshalb einmal:</p><ul><li><strong>Windows:</strong> Bei SmartScreen auf „Weitere Informationen“ → „Trotzdem ausführen“.</li><li><strong>macOS:</strong> Rechtsklick auf die App → „Öffnen“ → noch einmal „Öffnen“.</li></ul><p>Danach startet Shardwing ganz normal.</p></div><p>Intel-Macs werden derzeit nicht unterstützt.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Shardwing schaut beim Start und danach alle paar Stunden nach einer neuen Version. Gibt es eine, erscheint <strong>unten rechts</strong> ein Hinweis mit den Neuerungen. Installiert wird erst nach deinem Klick auf „Installieren und neu starten“ – hast du ungespeicherte Änderungen, fragt Shardwing vorher nach.</p><p>Jedes Update ist signiert und wird vor der Installation geprüft. Unsignierte Pakete lehnt die App ab.</p><h2 id="ohne-installation-im-browser" tabindex="-1">Ohne Installation: im Browser <a class="header-anchor" href="#ohne-installation-im-browser" aria-label="Permalink to &quot;Ohne Installation: im Browser&quot;">​</a></h2><p>Shardwing läuft auch im Browser (Chrome, Edge, Firefox, Safari). Der Unterschied:</p><table tabindex="0"><thead><tr><th></th><th>Desktop-App</th><th>Browser</th></tr></thead><tbody><tr><td>Öffnen</td><td>Dialog oder Datei ins Fenster ziehen</td><td>Dialog oder Datei ins Fenster ziehen</td></tr><tr><td>Speichern</td><td><strong>an derselben Stelle</strong>, mit Sicherung der alten Datei</td><td>als Download (in Chrome/Edge teils auch direkt)</td></tr><tr><td>Updates</td><td>automatisch</td><td>immer die neueste Version</td></tr><tr><td>Gemeinsam planen</td><td>✓</td><td>✓</td></tr></tbody></table><p>Piloten, die nur ihren Platz in einer geteilten Mission bearbeiten, brauchen nichts zu installieren: Sie öffnen einfach ihren Link im Browser. Mehr dazu unter <a href="/ablaeufe/pilot">Als Pilot</a>.</p><h2 id="sicherungen" tabindex="-1">Sicherungen <a class="header-anchor" href="#sicherungen" aria-label="Permalink to &quot;Sicherungen&quot;">​</a></h2><p>Die Desktop-App legt beim Speichern eine Kopie der vorherigen Datei ab, die letzten 30 pro Mission:</p><ul><li><strong>macOS:</strong> <code>~/Library/Application Support/de.shardwing.desktop/backups/</code></li><li><strong>Windows:</strong> im App-Datenordner von Shardwing (<code>%APPDATA%\\de.shardwing.desktop\\backups\\</code>)</li></ul><p>Geschrieben wird über eine temporäre Datei – auch bei einem Absturz entsteht nie eine halbe Mission.</p><h2 id="was-du-brauchst" tabindex="-1">Was du brauchst <a class="header-anchor" href="#was-du-brauchst" aria-label="Permalink to &quot;Was du brauchst&quot;">​</a></h2><ul><li>Eine <strong>Mission (.miz)</strong> aus dem DCS Mission Editor. Shardwing erstellt (noch) keine Missionen von Grund auf, sondern ergänzt bestehende.</li><li>Für Cartridges: <strong>F-16C</strong> oder <strong>F/A-18C</strong> in der Mission. Alle anderen Flugzeuge siehst du trotzdem mit Route, Funk, Beladung und Lineup Card.</li><li>Internet für die Kartenkacheln. Alles andere läuft lokal auf deinem Rechner.</li></ul><p><strong>Weiter:</strong> <a href="/start/erste-mission">Die erste Mission in 5 Minuten →</a></p>',21)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
